steps.sql:
SELECT nom, prix
FROM   produits
WHERE  prix > 10000;

SELECT nom FROM produits WHERE prix BETWEEN 8000 AND 22000;
SELECT nom FROM clients  WHERE ville IN ('Cotonou', 'Parakou');
SELECT nom FROM clients  WHERE nom LIKE 'A%';

SELECT nom, prix
FROM   produits
ORDER BY prix;

SELECT nom, prix
FROM   produits
ORDER BY prix DESC;

SELECT nom, prix * 1.18 AS ttc
FROM   produits
ORDER BY ttc DESC;

-- ❌ FAUX : ROWNUM est attribué AVANT le tri
SELECT nom, prix FROM produits
WHERE  ROWNUM <= 3
ORDER BY prix DESC;

-- ✅ BON : on trie dans une sous-requête, PUIS on limite
SELECT * FROM (
  SELECT nom, prix FROM produits ORDER BY prix DESC
)
WHERE ROWNUM <= 3;

SELECT client_id, COUNT(*) AS nb_cmd, SUM(montant) AS total
FROM   commandes
GROUP BY client_id;

SELECT nom, prix
FROM   produits
WHERE  prix > (SELECT AVG(prix) FROM produits);

SELECT nom FROM clients c
WHERE  NOT EXISTS (
  SELECT 1 FROM commandes cmd WHERE cmd.client_id = c.id
);
